(function(root){
 'use strict';
 const norm=t=>String(t||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
 const ink=strokes=>(strokes||[]).filter(s=>s.opacity!==.3&&s.points?.length);
 function signature(strokes){let a=2166136261,b=5381;const text=JSON.stringify(ink(strokes));for(let i=0;i<text.length;i++){const c=text.charCodeAt(i);a=Math.imul(a^c,16777619);b=Math.imul(b,33)^c;}return (a>>>0).toString(16)+(b>>>0).toString(16);}
 function bounds(s){let x=Infinity,y=Infinity,right=-Infinity,bottom=-Infinity;for(const p of s.points){x=Math.min(x,p[0]);y=Math.min(y,p[1]);right=Math.max(right,p[0]);bottom=Math.max(bottom,p[1]);}const pad=s.width||3;return {x:x-pad,y:y-pad,right:right+pad,bottom:bottom+pad,strokes:[s]};}
 function lines(strokes){const boxes=ink(strokes).map(bounds),heights=boxes.map(b=>b.bottom-b.y).filter(h=>h>8).sort((a,b)=>a-b),median=heights[Math.floor(heights.length/2)]||20,rows=[];
  for(const b of boxes.sort((a,b)=>(a.y+a.bottom)-(b.y+b.bottom))){const cy=(b.y+b.bottom)/2;let row=rows.find(r=>Math.abs(cy-(r.y+r.bottom)/2)<Math.max(median*.65,Math.min(b.bottom-b.y,r.bottom-r.y)*.65));if(!row){rows.push(b);continue;}row.x=Math.min(row.x,b.x);row.y=Math.min(row.y,b.y);row.right=Math.max(row.right,b.right);row.bottom=Math.max(row.bottom,b.bottom);row.strokes.push(...b.strokes);}
  // Small detached marks belong with a nearby word, rather than a new OCR line.
  for(const mark of rows.slice().filter(r=>r.bottom-r.y<median*.45)){const candidates=rows.filter(r=>r!==mark&&r.bottom-r.y>=median*.6).map(r=>({row:r,gap:Math.max(0,r.y-mark.bottom,mark.y-r.bottom),xgap:Math.max(0,r.x-mark.right,mark.x-r.right)})).filter(c=>c.gap<=median*.9&&c.xgap<=median*.7).sort((a,b)=>(a.gap+a.xgap*.5)-(b.gap+b.xgap*.5));const row=candidates[0]?.row;if(row){row.x=Math.min(row.x,mark.x);row.y=Math.min(row.y,mark.y);row.right=Math.max(row.right,mark.right);row.bottom=Math.max(row.bottom,mark.bottom);row.strokes.push(...mark.strokes);rows.splice(rows.indexOf(mark),1);}}
  return rows.sort((a,b)=>a.y-b.y||a.x-b.x).map(r=>({...r,width:r.right-r.x,height:r.bottom-r.y}));
 }
 function language(container){return container?.recognitionLanguage==='mr'?'mr':'en';}
 function currentIndex(container){const index=container?.handwriting;return index&&index.signature===signature(container.strokes)&&(index.reviewed||index.version>=(language(container)==='mr'?3:2)&&(index.language||'en')===language(container))?index:null;}
 function records(data){const out=[];for(const n of data.notes){const base={id:n.id,title:n.title||'Untitled note',book:n.book,updated:n.updated,star:n.star};out.push({...base,page:0,kind:'title',text:n.title||''});
  const pages=n.pdf?n.pdf.pages:[n];pages.forEach((p,i)=>{const page=n.pdf?i:0,add=(kind,text,rect)=>{if(text)out.push({...base,page,kind,text,rect,pdf:!!n.pdf});};for(const t of p.texts||[])add('typed',t.text,{x:t.x,y:t.y-t.size,width:t.width||Math.min(700,t.text.length*t.size*.65),height:Math.max(t.size*1.5,t.text.split('\n').length*t.size*(t.lineHeight||1.5))});for(const node of p.board?.nodes||[])add('typed',node.text,{x:node.x,y:node.y,width:node.width,height:node.height});if(p.pdfText)add('pdf',p.pdfText);const index=currentIndex(p);if(index){if(index.reviewed)add('handwriting',index.text);else for(const line of index.lines||[]){add('handwriting',line.text,line.rect);for(const alternate of line.alternatives||[])add('handwriting',alternate,line.rect);}}});
 }return out;}
 function search(data,query,kind='all'){const terms=norm(query).split(' ').filter(Boolean);if(!terms.length)return [];const found=records(data).filter(r=>(kind==='all'||r.kind===kind)&&terms.every(term=>norm(r.text).includes(term)));const grouped=new Map();for(const r of found){const key=r.id+':'+r.page;let hit=grouped.get(key);if(!hit){hit={...r,matches:[],rects:[]};grouped.set(key,hit);}hit.matches.push(r);if(r.rect)hit.rects.push(r.rect);if(r.kind!=='title'&&hit.kind==='title'){hit.text=r.text;hit.kind=r.kind;}}
  return [...grouped.values()].sort((a,b)=>b.updated-a.updated||a.page-b.page);
 }
 function validIndex(v){if(!v||typeof v.signature!=='string')return undefined;return {version:Number(v.version)||1,language:v.language==='mr'?'mr':'en',signature:v.signature.slice(0,100),text:String(v.text||'').slice(0,100000),reviewed:!!v.reviewed,updated:Number(v.updated)||0,lines:(Array.isArray(v.lines)?v.lines:[]).slice(0,2000).map(l=>({text:String(l.text||'').slice(0,5000),alternatives:(Array.isArray(l.alternatives)?l.alternatives:[]).slice(0,2).map(t=>String(t).slice(0,5000)),rect:l.rect&&['x','y','width','height'].every(k=>Number.isFinite(l.rect[k]))?l.rect:undefined}))};}
 const api={norm,signature,lines,language,currentIndex,records,search,validIndex};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.LeafSearch=api;
})(globalThis);
